      const retryUpdate = await env.DB
        .prepare(
          `UPDATE workspace_deployments
           SET status = 'queued',
               started_at = NULL,
               finished_at = NULL,
               error_code = 'retry_scheduled',
               error_message = ?,
               updated_at = ?
           WHERE id = ?
