export async function handleGetWorkspaceDeployment(
  workspaceId: string,
  deploymentId: string,
  env: Env,
  ctx?: ExecutionContext,
  authContext?: AuthContext
): Promise<Response> {
  const effectiveAuthContext =
    authContext ??
