  deployment = await getWorkspaceDeployment(env.DB, workspaceId, deploymentId);
  if (!deployment) {
    return jsonResponse({ error: 'Deployment not found' }, 404);
  }

  return jsonResponse({
    deployment,
    nextAction: nextActionForDeploymentError(deployment.error?.code),
  });
}

